function [contrast_summary,validation]=run_q5_procedure_subject001_estimation_contrast()
% Estimate subject001 Q5 Procedure and compute/validate intrinsic-load contrast.
repo_root=fileparts(fileparts(fileparts(mfilename('fullpath'))));glm='C:\aliceproject\GLM';fl=fullfile(glm,'first_level');root=fullfile(repo_root,'results','q5_intrinsic_procedure','cohort_specification','subject001');
addpath(fl);addpath(fullfile(glm,'toolboxes','spm'));addpath(genpath(fullfile(glm,'toolboxes','NIRS_SPM_v4_r1')));data_file=fullfile(fl,'nirs_spm_inputs_v2_fulltimeline_trial1','subject001','subject001_nirs_data.mat');D=load(data_file,'nirs_data');nch=D.nirs_data.nch;clear D
meta=readtable(fullfile(fl,'nirs_spm_inputs','subject001','subject001_channel_metadata.csv'),'TextType','string');assert(height(meta)==nch,'Metadata channel count mismatch.');contrast_summary=table();validation=table();
for hb=["HbO","HbR"]
 spm_file=fullfile(root,char(hb),sprintf('SPM_indiv_%s.mat',hb));L=load(spm_file,'SPM_nirs');S=L.SPM_nirs;
 if ~isfield(S.nirs,'step')||~strcmpi(string(S.nirs.step),'estimation'),nirs_spm_estimation_batch_fixed(spm_file,data_file);L=load(spm_file,'SPM_nirs');S=L.SPM_nirs;end
 beta=double(S.nirs.beta);assert(isequal(size(beta),[5 nch]),'%s beta must be 5x%d.',hb,nch);names=string(S.xX.name(:));expected=["LILEProcedure","HILEProcedure","LIHEProcedure","HIHEProcedure"];idx=zeros(4,1);for i=1:4,idx(i)=find(contains(names,expected(i)),1);end;assert(all(idx>0),'A required Q5 regressor is missing.');ic=find(contains(lower(names),'constant'),1);assert(~isempty(ic),'Constant is missing.');c=zeros(5,1);c(idx)=[-.5 .5 -.5 .5];assert(c(ic)==0,'Constant weight must be zero.');
 rss=double(S.nirs.ResSS);if isvector(rss),rss=rss(:)';else,rss=diag(rss)';end;df=double(S.xX.erdf);cv=max((c'*double(S.xX.Bcov)*c).*(rss./df),0);cb=c'*beta;se=sqrt(cv);ts=cb./se;p=betainc(df./(df+ts.^2),df/2,.5);q=bh(p);
 R=table(repmat("subject001",nch,1),repmat(hb,nch,1),(1:nch)',string(meta.channel_id),string(meta.channel_type),string(meta.roi),string(meta.laterality),cb(:),se(:),ts(:),p(:),q(:),repmat(join(string(c'),' '),nch,1),'VariableNames',{'subject_id','hemoglobin','channel_index','channel_id','channel_type','roi','laterality','contrast_beta','contrast_se','contrast_t','contrast_p_two_sided','contrast_q_bh61','contrast_vector'});writetable(R,fullfile(root,sprintf('subject001_%s_q5_high_intrinsic_minus_low_intrinsic_procedure_channel_contrasts.csv',hb)));
 contrast_summary=[contrast_summary;table(hb,nch,sum(p<.05),sum(q<.05),mean(cb),median(cb),'VariableNames',{'hemoglobin','n_channels','n_p_lt_005','n_q_bh61_lt_005','mean_contrast_beta','median_contrast_beta'})]; %#ok<AGROW>
 validation=[validation;table(hb,string(strjoin(cellstr(names(idx))', ' | ')),string(join(string(c'),' ')),size(beta,1),size(beta,2),df,all(isfinite(beta),'all'),all(isfinite(cb)),'VariableNames',{'hemoglobin','located_task_regressors','implemented_contrast','n_beta_rows','n_channels','effective_df','beta_all_finite','contrast_all_finite'})]; %#ok<AGROW>
end
writetable(contrast_summary,fullfile(root,'subject001_q5_procedure_contrast_summary.csv'));writetable(validation,fullfile(root,'subject001_q5_procedure_contrast_validation.csv'));disp(validation);disp(contrast_summary);
end
function q=bh(p),q=nan(size(p));v=isfinite(p);pv=p(v);[s,o]=sort(pv(:));m=numel(s);z=min(1,flipud(cummin(flipud(s.*m./(1:m)'))));qv=zeros(size(pv));qv(o)=z;q(v)=qv;end
